/** Build RGBA pixel data of a single flat colour. */
function solid(pixels: number, value: number): Uint8ClampedArray {
	const data = new Uint8ClampedArray(pixels * 4);
	for (let i = 0; i < pixels; i += 1) {
		data[i * 4] = value;
		data[i * 4 + 1] = value;
		data[i * 4 + 2] = value;
		data[i * 4 + 3] = 255;
	}
	return data;
}

