		expect(normalizeCaptureOptions({ intervalMs: -5000 }).intervalMs).toBe(MIN_FRAME_INTERVAL_MS);
	});

	test("keeps intervals slower than the floor", () => {
		expect(normalizeCaptureOptions({ intervalMs: 5000 }).intervalMs).toBe(5000);
	});

