			<span
				aria-hidden="true"
				className={css({
					flex: "1 1 auto",
					minWidth: "0.75rem",
					alignSelf: "center",
					borderBottom: "1px dotted currentColor",
					opacity: 0.35,
				})}
			/>
			<span
				className={css({
					whiteSpace: "nowrap",
					flexShrink: 0,
					color: tone === "fail"
						? "var(--red)"
						: tone === "pending"
							? "var(--amber)"
							: "var(--phosphor)",
				})}
			>
				{value}
			</span>
		</div>
	);
}

