716				const requiredProvider = liveCredentialProvider(settings.providerId);
717				const credential = requiredProvider
718					? getProviderApiKey(requiredProvider)
719					: resolveSpeechCredential(getProviderApiKey).then((value) => value?.apiKey);
720				credential
721					.then((apiKey) => {
722						if (!cancelled) setAvailable(Boolean(apiKey));
723					})
724	        .catch(() => {
725	          if (!cancelled) setAvailable(false);
726	        });
