description: Expose model label and picker from the agent hook
command: python3 - <<'PYEOF'
p='src/hooks/useKeatingAgent.tsx'
s=open(p).read()

s=s.replace('''  const selectedModelRef = useRef<Model<Api>>(DEFAULT_MODEL);''','''  const selectedModelRef = useRef<Model<Api>>(DEFAULT_MODEL);
  // The ref is what the agent reads; this mirrors it for anything that has to
  // re-render when the model changes, such as the chat header's model button.
  const [modelLabel, setModelLabel] = useState<string>(DEFAULT_MODEL.name ?? DEFAULT_MODEL.id);
  const selectModel = useCallback((model: Model<Api>) => {
    selectedModelRef.current = model;
    setModelLabel(model.name ?? model.id);
  }, []);''',1)

for old in ['    selectedModelRef.current = resolvedModel;',
            '    selectedModelRef.current = session.model;',
            '          selectedModelRef.current = model;']:
    indent = old[:len(old)-len(old.lstrip())]
    value = old.strip().split('= ',1)[1].rstrip(';')
    s=s.replace(old, f'{indent}selectModel({value});',1)

s=s.replace('''    // Top-level actions
    openSettings,''','''    // Top-level actions
    openSettings,
    modelLabel,
    openModelSelector: modelSelectorDialog.onOpen,''',1)
open(p,'w').write(s)
print('ok')
PYEOF
bunx tsc --noEmit -p tsconfig.json 2>&1 | head -10
[/external_agent_tool_call]

